bear: 存储周期、客户集中、资本开支与新ADS摊薄；ADS比为十分之一，不能倒置；财报期末股数尚未包含7月发行，必须摊薄；存储仍按周期研究
verdict: 业务事实与价格结论分开；中周期EPS与DCF未交叉闭合，保留观察/等待证据

